    try:
        try:
            raise ValueError
        finally:
            print('finally 1')
        print('got here')
    finally:
        print('finally 2')
        return 2
    print('got here')
print(f())

# nested, return in inner
def f():
    try:
        try:
            raise ValueError
        finally:
            print('finally 1')
            return 1
        print('got here')
    finally:
        print('finally 2')
    print('got here')
print(f())

# nested, return in inner and outer
def f():
    try:
        try:
            raise ValueError
        finally:
            print('finally 1')
            return 1
        print('got here')
    finally:
        print('finally 2')
        return 2
    print('got here')
print(f())

# nested with reraise
def f():
    try:
        try:
            raise ValueError
        except:
            raise
        print('got here')
    finally:
        print('finally')
        return 0
    print('got here')
print(f())

