# test 'return' within the finally block, with nested finally's
# only inactive finally's should be executed, and only once

# basic nested finally's, the print should only be executed once
def f():
    try:
        raise TypeError
    finally:
        print(1)
        try:
            raise ValueError
        finally:
            return 42
print(f())

# similar to above but more nesting
def f():
    try:
        raise ValueError
    finally:
        print(1)
        try:
            raise TypeError
        finally:
            print(2)
            try:
                pass
            finally:
                return 42
print(f())

# similar to above but even more nesting
def f():
    try:
        raise ValueError
    finally:
        print(1)
        try:
            raise TypeError
        finally:
            print(2)
            try:
                raise Exception
            finally:
                print(3)
                return 42
print(f())

# upon return some try's are active, some finally's are active, some inactive
def f():
    try:
        try:
            pass
        finally:
            print(2)
            return 42
    finally:
        print(1)
print(f())

# same as above but raise instead of pass
def f():
    try:
        try:
            raise ValueError
        finally:
            print(2)
            return 42
    finally:
        print(1)
print(f())

# upon return exception stack holds: active finally, inactive finally, active finally
def f():
    try:
        raise Exception
    finally:
        print(1)
        try:
            try:
                pass
            finally:
                print(3)
                return 42
        finally:
            print(2)
print(f())

# same as above but raise instead of pass in innermost try block
def f():
    try:
        raise Exception
    finally:
        print(1)
        try:
            try:
                raise Exception
            finally:
                print(3)
                return 42
        finally:
            print(2)
print(f())
=== tests/basics/try_finally_return4.py ===
# test try-finally with return, where unwinding return has to go through
# another try-finally which may affect the behaviour of the return

# case where a simple try-finally executes during an unwinding return
def f(x):
    try:
        try:
            if x:
                return 42
        finally:
            try:
                print(1)
            finally:
                print(2)
            print(3)
        print(4)
    finally:
        print(5)
print(f(0))
print(f(1))

# case where an unwinding return is replaced by another one
def f(x):
    try:
        try:
            if x:
                return 42
        finally:
            try:
                print(1)
                return 43
            finally:
                print(2)
            print(3)
        print(4)
    finally:
        print(5)
print(f(0))
print(f(1))

# case where an unwinding return is cancelled by an exception
def f(x):
    try:
        try:
            if x:
                return 42
        finally:
            try:
                print(1)
                raise ValueError # cancels any active return
            finally:
                print(2)
            print(3)
        print(4)
    finally:
        print(5)
try:
    print(f(0))
except:
    print('caught')
try:
    print(f(1))
except:
    print('caught')

# case where an unwinding return is cancelled then resumed
def f(x):
    try:
        try:
            if x:
                return 42
        finally:
            try:
                print(1)
                raise Exception # cancels any active return
            except: # cancels the exception and resumes any active return
                print(2)
            print(3)
        print(4)
    finally:
        print(5)
print(f(0))
print(f(1))
